			            msCrudType = "UPDATE";
			            
			            if(regUseYn == 'Y') util.Control.setVisible(app,  true,  ["btnTrprInsert"]);        // 대상자등록            
			            if(regUseYn == 'Y') util.Control.setVisible(app,  true,  ["btnSave",   "btnRestore"]);                          // 저장, 취소
			            util.Control.setVisible(app,  false, ["btnUpdate", "btnDelete", "btnList", "btnClose"]);    // 수정, 삭제, 목록, 닫기
			            util.Control.setVisible(app,  true, ["btnTrprInsertRead"]); // 대상자정보
